mapper.select:
SELECT o.id, o.order_no, o.order_type, o.member_id, m.real_name AS member_name, o.session_id, o.total_amount, o.discount_amount, o.payable_amount, o.paid_amount, o.status, o.remark, o.operator_id, e.real_name AS operator_name, o.paid_at, o.created_at, o.updated_at FROM orders o LEFT JOIN member m ON o.member_id = m.id AND m.deleted_at IS NULL LEFT JOIN employee e ON o.operator_id = e.id AND e.deleted_at IS NULL WHERE o.deleted_at IS NULL
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.order_type = #{orderType}
AND o.status = #{status}
AND o.status IN
#{s}
AND o.member_id = #{memberId}
AND o.paid_at >= #{startTime}
AND o.paid_at <= #{endTime}
ORDER BY o.created_at DESC
